// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-segmented-button-set.js';
import './md-gb-segmented-button.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** The index of the item that holds focus (also inside its shadow root), or -1. */
function focusedIndex(items: Element[]) {
  const path: Element[] = [];
  let el = document.activeElement;
  while (el) {
    path.push(el);
    el = el.shadowRoot?.activeElement ?? null;
  }
  return items.findIndex((item) => path.some((e) => e === item || item.contains(e)));
}

/** Focuses item `index` (negative counts from the end). */
async function focusItem(f: {items: HTMLElement[]}, index: number) {
  f.items[(index + f.items.length) % f.items.length].focus();
  await settle();
}

async function setup(opts: {dir?: string; disabled?: number} = {}) {
  const root = await mount(html`
    <button id="before">Before</button>
    <div dir=${opts.dir ?? 'ltr'}>
      <md-gb-segmented-button-set aria-label="View">
      <md-gb-segmented-button value="Alpha">Alpha</md-gb-segmented-button>
      <md-gb-segmented-button value="Bravo">Bravo</md-gb-segmented-button>
      <md-gb-segmented-button value="Charlie">Charlie</md-gb-segmented-button>
      <md-gb-segmented-button value="Delta">Delta</md-gb-segmented-button>
      </md-gb-segmented-button-set>
    </div>
    <button id="after">After</button>
  `);
  const items = [...root.querySelectorAll<HTMLElement>('md-gb-segmented-button')];
  if (opts.disabled !== undefined) {
    items[opts.disabled].setAttribute('disabled', '');
    await settle();
  }
  return {
    group: root.querySelector<HTMLElement>('md-gb-segmented-button-set')!,
    items,
    before: root.querySelector<HTMLElement>('#before')!,
    after: root.querySelector<HTMLElement>('#after')!,
  };
}

describe('<md-gb-segmented-button-set> roving focus contract (RovingFocusController: both, wrap, Home/End, one tab stop)', () => {
  afterEach(() => container?.remove());

  it('is entered with Tab on the first item; the container takes no focus', async () => {
    // spec: segmented-buttons-e08c31, segmented-buttons-4c08e6
    const f = await setup();
    f.before.focus();
    await press('Tab');
    expect(focusedIndex(f.items)).toBe(0);
    expect(f.group.matches(':focus')).toBeFalse();
  });

  it('moves focus to the next and previous item with ArrowRight / ArrowLeft', async () => {
    // spec: segmented-buttons-e7c14b, segmented-buttons/accessibility/use-cases/keyboard-navigation
    const f = await setup();
    await focusItem(f, 1);
    await press('ArrowRight');
    expect(focusedIndex(f.items)).toBe(2);
    await press('ArrowLeft');
    await press('ArrowLeft');
    expect(focusedIndex(f.items)).toBe(0);
  });

  it('also moves with ArrowDown / ArrowUp', async () => {
    // spec: segmented-buttons-e7c14b, segmented-buttons/accessibility/use-cases/keyboard-navigation
    const f = await setup();
    await focusItem(f, 1);
    await press('ArrowDown');
    expect(focusedIndex(f.items)).toBe(2);
    await press('ArrowUp');
    expect(focusedIndex(f.items)).toBe(1);
  });

  it('wraps from the last item to the first and back', async () => {
    // spec: segmented-buttons-e7c14b, segmented-buttons/accessibility/use-cases/keyboard-navigation
    const f = await setup();
    await focusItem(f, -1);
    await press('ArrowRight');
    expect(focusedIndex(f.items)).toBe(0);
    await press('ArrowLeft');
    expect(focusedIndex(f.items)).toBe(f.items.length - 1);
  });

  it('mirrors Left and Right in right-to-left layouts, and Tab still enters on the first item', async () => {
    // spec: segmented-buttons-40eeca, segmented-buttons-3f65bc
    const f = await setup({dir: 'rtl'});
    f.before.focus();
    await press('Tab');
    expect(focusedIndex(f.items)).toBe(0);
    await press('ArrowLeft');
    expect(focusedIndex(f.items)).toBe(1);
    await press('ArrowRight');
    expect(focusedIndex(f.items)).toBe(0);
  });

  it('moves to the first and last item with Home and End', async () => {
    const f = await setup();
    await focusItem(f, 1);
    await press('End');
    expect(focusedIndex(f.items)).toBe(f.items.length - 1);
    await press('Home');
    expect(focusedIndex(f.items)).toBe(0);
  });

  it('skips disabled items', async () => {
    const f = await setup({disabled: 1});
    await focusItem(f, 0);
    await press('ArrowRight');
    expect(focusedIndex(f.items)).toBe(2);
  });

  it('is one tab stop that remembers the last focused item', async () => {
    // spec: segmented-buttons-e7c14b
    const f = await setup();
    await focusItem(f, 0);
    await press('ArrowRight');
    await press('ArrowRight');
    await press('Tab');
    expect(document.activeElement).toBe(f.after);
    await press('Shift+Tab');
    expect(focusedIndex(f.items)).toBe(2);
  });
});

/** The form's entries, as submitted. */
function submittedEntries(form: HTMLFormElement) {
  return [...new FormData(form).entries()].map(([k, v]) => [k, String(v)]);
}

async function setupFormGroup(
  attrs: Record<string, string> = {},
  on: number[] = [],
  off: number[] = [],
) {
  const root = await mount(html`
    <form>
      <fieldset>
        <md-gb-segmented-button-set name="pick" aria-label="Pick" ?multiselect=${'multiselect' in attrs} ?required=${'required' in attrs}>
        <md-gb-segmented-button value="a" ?selected=${on.includes(0)} ?disabled=${off.includes(0)}>Alpha</md-gb-segmented-button>
        <md-gb-segmented-button value="b" ?selected=${on.includes(1)} ?disabled=${off.includes(1)}>Beta</md-gb-segmented-button>
        <md-gb-segmented-button value="c" ?selected=${on.includes(2)} ?disabled=${off.includes(2)}>Gamma</md-gb-segmented-button>
        </md-gb-segmented-button-set>
      </fieldset>
    </form>
  `);
  const el = root.querySelector<any>('md-gb-segmented-button-set')!;
  await settle();
  return {
    el,
    form: root.querySelector('form')!,
    fieldset: root.querySelector('fieldset')!,
    items: [...el.children] as any[],
  };
}

/** Selects or unselects item `index` with Space on the focused item. */
async function toggleFormGroup(f: {items: HTMLElement[]}, index: number) {
  f.items[index].focus();
  await press('Space');
}

describe('<md-gb-segmented-button-set> form contract (shared form layer)', () => {
  afterEach(() => container?.remove());

  it('submits one entry per selected item under the name of the set', async () => {
    // spec: segmented-buttons-79f767, segmented-buttons-ad49bf
    const f = await setupFormGroup({'multiselect':''});
    expect(submittedEntries(f.form)).toEqual([]);
    await toggleFormGroup(f, 0);
    await toggleFormGroup(f, 2);
    expect(f.el.values).toEqual(['a', 'c']);
    expect(submittedEntries(f.form)).toEqual([['pick', 'a'], ['pick', 'c']]);
    await toggleFormGroup(f, 0);
    expect(submittedEntries(f.form)).toEqual([['pick', 'c']]);
  });

  it('submits only the selected item of a single-select set', async () => {
    // spec: segmented-buttons-79f767, segmented-buttons-ad49bf
    const f = await setupFormGroup({});
    await toggleFormGroup(f, 0);
    await toggleFormGroup(f, 1);
    expect(f.el.value).toBe('b');
    expect(submittedEntries(f.form)).toEqual([['pick', 'b']]);
  });

  it('starts with the selected items and resets to them', async () => {
    // spec: segmented-buttons-79f767, segmented-buttons-ad49bf
    const f = await setupFormGroup({'multiselect':''}, [0, 2]);
    expect(submittedEntries(f.form)).toEqual([['pick', 'a'], ['pick', 'c']]);
    await toggleFormGroup(f, 1);
    await toggleFormGroup(f, 0);
    expect(submittedEntries(f.form)).toEqual([['pick', 'b'], ['pick', 'c']]);
    f.form.reset();
    await settle();
    expect(f.items.map((item) => item.selected)).toEqual([true, false, true]);
    expect(submittedEntries(f.form)).toEqual([['pick', 'a'], ['pick', 'c']]);
  });

  it('resets a single-select set to its default or to none', async () => {
    // spec: segmented-buttons-79f767, segmented-buttons-ad49bf
    const f = await setupFormGroup({}, [1]);
    await toggleFormGroup(f, 0);
    expect(submittedEntries(f.form)).toEqual([['pick', 'a']]);
    f.form.reset();
    await settle();
    expect(submittedEntries(f.form)).toEqual([['pick', 'b']]);

    const none = await setupFormGroup({});
    await toggleFormGroup(none, 0);
    none.form.reset();
    await settle();
    expect(none.items.map((item) => item.selected)).toEqual([false, false, false]);
    expect(submittedEntries(none.form)).toEqual([]);
  });

  it('restores the saved selection', async () => {
    // spec: segmented-buttons-79f767, segmented-buttons-ad49bf
    const f = await setupFormGroup({'multiselect':''}, [0]);
    const saved = new FormData();
    saved.append('pick', 'b');
    saved.append('pick', 'c');
    f.el.formStateRestoreCallback(saved, 'restore');
    await settle();
    expect(f.items.map((item) => item.selected)).toEqual([false, true, true]);
    expect(submittedEntries(f.form)).toEqual([['pick', 'b'], ['pick', 'c']]);
    f.el.formStateRestoreCallback(null, 'restore');
    await settle();
    expect(submittedEntries(f.form)).toEqual([]);
  });

  it('restores a saved single value', async () => {
    // spec: segmented-buttons-79f767, segmented-buttons-ad49bf
    const f = await setupFormGroup({});
    f.el.formStateRestoreCallback('b', 'restore');
    await settle();
    expect(f.items.map((item) => item.selected)).toEqual([false, true, false]);
    expect(submittedEntries(f.form)).toEqual([['pick', 'b']]);
  });

  it('is invalid while required and nothing is selected, valid once selected', async () => {
    // spec: segmented-buttons-79f767
    const f = await setupFormGroup({required: ''});
    expect(f.el.validity.valueMissing).toBeTrue();
    expect(f.form.checkValidity()).toBeFalse();
    await toggleFormGroup(f, 1);
    expect(f.el.validity.valid).toBeTrue();
    expect(f.form.checkValidity()).toBeTrue();
    // The selected segment can't be unselected, so the set stays valid.
    await toggleFormGroup(f, 1);
    expect(f.form.checkValidity()).toBeTrue();
  });

  it('does not require a selection in a multi-select set', async () => {
    // spec: segmented-buttons-79f767
    const f = await setupFormGroup({required: '', multiselect: ''});
    expect(f.form.checkValidity()).toBeTrue();
  });

  it('setCustomValidity() invalidates until cleared', async () => {
    // spec: segmented-buttons-79f767
    const f = await setupFormGroup();
    f.el.setCustomValidity('Pick two');
    expect(f.el.validity.customError).toBeTrue();
    expect(f.el.validationMessage).toBe('Pick two');
    expect(f.form.checkValidity()).toBeFalse();
    f.el.setCustomValidity('');
    expect(f.el.validity.valid).toBeTrue();
  });

  it('blocks a submit while invalid and lets it through once valid', async () => {
    // spec: segmented-buttons-79f767
    const f = await setupFormGroup({required: ''});
    let submitted = 0;
    f.form.addEventListener('submit', (e) => {
      e.preventDefault();
      submitted++;
    });
    f.form.requestSubmit();
    expect(submitted).toBe(0);
    await toggleFormGroup(f, 0);
    await settle();
    f.form.requestSubmit();
    expect(submitted).toBe(1);
  });

  it('follows a disabled fieldset, is left out of the form and recovers', async () => {
    // spec: segmented-buttons-9bbe3e
    const f = await setupFormGroup({'multiselect':''}, [0]);
    expect(f.el.disabled).toBeFalse();
    f.fieldset.disabled = true;
    await settle();
    expect(f.el.disabled).toBeTrue();
    expect(f.items.every((item) => item.effectivelyDisabled)).toBeTrue();
    expect(submittedEntries(f.form)).toEqual([]);
    await toggleFormGroup(f, 1);
    expect(f.items.map((item) => item.selected)).toEqual([true, false, false]);
    f.fieldset.disabled = false;
    await settle();
    expect(f.el.disabled).toBeFalse();
    expect(f.items.some((item) => item.effectivelyDisabled)).toBeFalse();
    expect(submittedEntries(f.form)).toEqual([['pick', 'a']]);
    await toggleFormGroup(f, 1);
    expect(submittedEntries(f.form)).toEqual([['pick', 'a'], ['pick', 'b']]);
  });

  it('keeps an item that is disabled itself disabled after the set recovers', async () => {
    // spec: segmented-buttons-9bbe3e
    const f = await setupFormGroup({'multiselect':''}, [], [2]);
    f.fieldset.disabled = true;
    await settle();
    f.fieldset.disabled = false;
    await settle();
    expect(f.items.map((item) => item.effectivelyDisabled)).toEqual([false, false, true]);
  });
});


const SELECTION_LABELS = ["Alpha","Bravo","Charlie","Delta"];
const SELECTION_MODE_ATTRS: {[mode: string]: string} = {"single":"","multiple":"multiselect"};

interface SelectionFixture {
  form: HTMLFormElement;
  group: HTMLElement;
  items: HTMLElement[];
}

async function setupSelection(opts: {
  mode: string;
  required?: boolean;
  disabled?: number;
  name?: boolean;
}): Promise<SelectionFixture> {
  const root = await mount(html``);
  const attrs = [
    SELECTION_MODE_ATTRS[opts.mode],
    opts.required ? 'required' : '',
    opts.name ? 'name="view"' : '',
  ]
    .filter(Boolean)
    .map((attr) => ' ' + attr)
    .join('');
  const item = (label: string, extra: string) => `<md-gb-segmented-button value="${label}"${extra}>${label}</md-gb-segmented-button>`;
  const items = SELECTION_LABELS.map((label, i) => item(label, opts.disabled === i ? ' disabled' : '')).join('');
  root.innerHTML = `<form><md-gb-segmented-button-set aria-label="View"${attrs}>${items}</md-gb-segmented-button-set></form>`;
  await settle();
  const f = {
    form: root.querySelector('form')!,
    group: root.querySelector<HTMLElement>('md-gb-segmented-button-set')!,
    items: [...root.querySelectorAll<HTMLElement>('md-gb-segmented-button')],
  };
  await settle();
  return f;
}

/** The labels of the selected items, in order. */
function selectedLabels(f: SelectionFixture) {
  return f.items.filter((item) => (item as HTMLElement & {selected: boolean}).selected).map((item) => item.textContent!.trim());
}

/** The ARIA state of each item. */
function ariaStates(f: SelectionFixture) {
  return f.items.map((item) => item.shadowRoot!.querySelector('button')?.getAttribute('aria-checked') ?? null);
}

/** The event types the group dispatches, in order. */
function recordSelectionEvents(group: HTMLElement) {
  const log: string[] = [];
  for (const type of ['input', 'change']) group.addEventListener(type, () => log.push(type));
  return log;
}

/** The values the form submits for the group. */
function formEntries(f: SelectionFixture) {
  return new FormData(f.form).getAll('view') as string[];
}


describe('<md-gb-segmented-button-set> selection contract (SelectionController: single, multiple, required)', () => {
  afterEach(() => container?.remove());

  it('selects the clicked item and unselects the previous one (single-select)', async () => {
    // spec: segmented-buttons-79f767, segmented-buttons-337f94, segmented-buttons-9e32e7
    const f = await setupSelection({mode: 'single'});
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Bravo']);
    f.items[2].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Charlie']);
  });

  it('selects the focused item with Space and with Enter', async () => {
    // spec: segmented-buttons-79dd8e, segmented-buttons-8e637f, segmented-buttons-01263b, segmented-buttons-4e972d
    const f = await setupSelection({mode: 'single'});
    await focusItem(f, 1);
    await press('Space');
    expect(selectedLabels(f)).toEqual(['Bravo']);
    await focusItem(f, 2);
    await press('Enter');
    expect(selectedLabels(f)).toEqual(['Charlie']);
  });

  it('toggles items independently in multi-select', async () => {
    // spec: segmented-buttons-ad49bf, segmented-buttons-a6ff04, segmented-buttons-244706, segmented-buttons-160c2f, segmented-buttons-44b2d9, segmented-buttons-7fabff
    const f = await setupSelection({mode: 'multiple'});
    f.items[0].click();
    f.items[2].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Alpha', 'Charlie']);
    f.items[0].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Charlie']);
  });

  it('selects and unselects the focused item with Space and Enter (multi-select)', async () => {
    // spec: segmented-buttons-ad49bf, segmented-buttons-a6ff04, segmented-buttons-244706, segmented-buttons-160c2f, segmented-buttons-44b2d9, segmented-buttons-7fabff
    const f = await setupSelection({mode: 'multiple'});
    await focusItem(f, 0);
    await press('Space');
    await focusItem(f, 1);
    await press('Enter');
    expect(selectedLabels(f)).toEqual(['Alpha', 'Bravo']);
    await focusItem(f, 0);
    await press('Space');
    expect(selectedLabels(f)).toEqual(['Bravo']);
    await focusItem(f, 1);
    await press('Enter');
    expect(selectedLabels(f)).toEqual([]);
  });

  it('lets every item be selected, or none, in multi-select even when required', async () => {
    // spec: segmented-buttons-ad49bf, segmented-buttons-a6ff04, segmented-buttons-244706, segmented-buttons-160c2f, segmented-buttons-44b2d9, segmented-buttons-7fabff
    const f = await setupSelection({mode: 'multiple', required: true});
    for (const item of f.items) item.click();
    await settle();
    expect(selectedLabels(f)).toEqual(SELECTION_LABELS);
    for (const item of f.items) item.click();
    await settle();
    expect(selectedLabels(f)).toEqual([]);
  });

  it('keeps the selected item selected when required, but still switches', async () => {
    const f = await setupSelection({mode: 'single', required: true});
    f.items[1].click();
    await settle();
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Bravo']);
    await focusItem(f, 1);
    await press('Space');
    await press('Enter');
    expect(selectedLabels(f)).toEqual(['Bravo']);
    f.items[3].click();
    await settle();
    expect(selectedLabels(f)).toEqual(['Delta']);
  });

  it('unselects the selected item when it is activated again (not required)', async () => {
    // spec: segmented-buttons-79dd8e
    const f = await setupSelection({mode: 'single'});
    f.items[1].click();
    await settle();
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual([]);
    await focusItem(f, 2);
    await press('Space');
    expect(selectedLabels(f)).toEqual(['Charlie']);
    await press('Enter');
    expect(selectedLabels(f)).toEqual([]);
  });

  it('reflects the selection as aria-checked on each item', async () => {
    // spec: segmented-buttons-5e14ea, segmented-buttons-3c4a1d
    const f = await setupSelection({mode: 'single'});
    expect(ariaStates(f)).toEqual(['false', 'false', 'false', 'false']);
    f.items[1].click();
    await settle();
    expect(ariaStates(f)).toEqual(['false', 'true', 'false', 'false']);
    f.items[1].click();
    await settle();
    expect(ariaStates(f)).toEqual(['false', 'false', 'false', 'false']);
  });

  it('reflects every selected item as aria-checked in multi-select', async () => {
    // spec: segmented-buttons-5e14ea, segmented-buttons-3c4a1d
    const f = await setupSelection({mode: 'multiple'});
    f.items[0].click();
    f.items[2].click();
    await settle();
    expect(ariaStates(f)).toEqual(['true', 'false', 'true', 'false']);
  });

  it('is a radio group in single-select and a checkbox group in multi-select', async () => {
    // spec: segmented-buttons-5e14ea, segmented-buttons-3c4a1d, segmented-buttons-7f895a
    const single = await setupSelection({mode: 'single'});
    expect(single.items.map((item) => item.shadowRoot!.querySelector('button')?.getAttribute('role'))).toEqual(
      SELECTION_LABELS.map(() => 'radio'),
    );
    const multiple = await setupSelection({mode: 'multiple'});
    expect(multiple.items.map((item) => item.shadowRoot!.querySelector('button')?.getAttribute('role'))).toEqual(
      SELECTION_LABELS.map(() => 'checkbox'),
    );
  });

  it('fires input then change on the group when the user selects, by click and by key', async () => {
    const f = await setupSelection({mode: 'single'});
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await settle();
    expect(log).toEqual(['input', 'change']);
    log.length = 0;
    await focusItem(f, 2);
    await press('Space');
    expect(log).toEqual(['input', 'change']);
  });

  it('fires no events when the selection is changed programmatically', async () => {
    const f = await setupSelection({mode: 'single'});
    const log = recordSelectionEvents(f.group);
    (f.items[2] as HTMLElement & {selected: boolean}).selected = true;
    await settle();
    expect(selectedLabels(f)).toContain('Charlie');
    expect(log).toEqual([]);
  });

  it('fires no events when nothing changes (the selected item of a required group)', async () => {
    const f = await setupSelection({mode: 'single', required: true});
    f.items[1].click();
    await settle();
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await settle();
    expect(log).toEqual([]);
  });

  it('does not select a disabled item', async () => {
    const f = await setupSelection({mode: 'single', disabled: 1});
    const before = selectedLabels(f);
    const log = recordSelectionEvents(f.group);
    f.items[1].click();
    await settle();
    expect(selectedLabels(f)).toEqual(before);
    expect(log).toEqual([]);
  });

  it('submits the selected value (single-select)', async () => {
    const f = await setupSelection({mode: 'single', name: true});
    expect(formEntries(f)).toEqual([]);
    f.items[1].click();
    await settle();
    expect(formEntries(f)).toEqual(['Bravo']);
    f.items[2].click();
    await settle();
    expect(formEntries(f)).toEqual(['Charlie']);
  });

  it('submits one entry per selected item (multi-select)', async () => {
    const f = await setupSelection({mode: 'multiple', name: true});
    f.items[0].click();
    f.items[2].click();
    await settle();
    expect(formEntries(f)).toEqual(['Alpha', 'Charlie']);
  });

  it('has the form value updated before the events fire, and restores it on form reset', async () => {
    const f = await setupSelection({mode: 'single', name: true});
    let atChange: string[] = [];
    f.group.addEventListener('change', () => (atChange = formEntries(f)));
    f.items[3].click();
    await settle();
    expect(atChange).toEqual(['Delta']);
    f.form.reset();
    await settle();
    expect(formEntries(f)).toEqual([]);
    expect(selectedLabels(f)).toEqual([]);
  });
});
